from unittest.mock import patch
from cookiecutter.exceptions import UnknownTemplateDirException
from cookiecutter.find import find_template

with patch(
    "cookiecutter.find.os.listdir",
    return_value=["{{cookiecutter.one}}", "{{cookiecutter.two}}"],
):
    try:
        find_template("repository")
    except UnknownTemplateDirException:
        pass
    else:
        raise AssertionError("ambiguous templates were silently accepted")

